mapper.select:
select
coalesce(sum(case when o.updated_at >= #{ranges.today.currentStart}
    and o.updated_at < #{ranges.today.currentEnd} then o.total_amount else 0 end), 0) as todayCurrent,
coalesce(sum(case when o.updated_at >= #{ranges.today.previousStart}
    and o.updated_at < #{ranges.today.previousEnd} then o.total_amount else 0 end), 0) as todayPrevious,
coalesce(sum(case when o.updated_at >= #{ranges.today.yearAgoStart}
    and o.updated_at < #{ranges.today.yearAgoEnd} then o.total_amount else 0 end), 0) as todayYearAgo,
sum(case when o.updated_at >= #{ranges.today.yearAgoStart}
    and o.updated_at < #{ranges.today.yearAgoEnd} then 1 else 0 end) as todayYearAgoCount,
coalesce(sum(case when o.updated_at >= #{ranges.week.currentStart}
    and o.updated_at < #{ranges.week.currentEnd} then o.total_amount else 0 end), 0) as weekCurrent,
coalesce(sum(case when o.updated_at >= #{ranges.week.previousStart}
    and o.updated_at < #{ranges.week.previousEnd} then o.total_amount else 0 end), 0) as weekPrevious,
coalesce(sum(case when o.updated_at >= #{ranges.week.yearAgoStart}
    and o.updated_at < #{ranges.week.yearAgoEnd} then o.total_amount else 0 end), 0) as weekYearAgo,
sum(case when o.updated_at >= #{ranges.week.yearAgoStart}
    and o.updated_at < #{ranges.week.yearAgoEnd} then 1 else 0 end) as weekYearAgoCount,
coalesce(sum(case when o.updated_at >= #{ranges.month.currentStart}
    and o.updated_at < #{ranges.month.currentEnd} then o.total_amount else 0 end), 0) as monthCurrent,
coalesce(sum(case when o.updated_at >= #{ranges.month.previousStart}
    and o.updated_at < #{ranges.month.previousEnd} then o.total_amount else 0 end), 0) as monthPrevious,
coalesce(sum(case when o.updated_at >= #{ranges.month.yearAgoStart}
    and o.updated_at < #{ranges.month.yearAgoEnd} then o.total_amount else 0 end), 0) as monthYearAgo,
sum(case when o.updated_at >= #{ranges.month.yearAgoStart}
    and o.updated_at < #{ranges.month.yearAgoEnd} then 1 else 0 end) as monthYearAgoCount
from biz_order o
where o.tenant_id = #{tenantId}
  and o.status = 'PAID'
  and o.deleted = 0
  and o.updated_at >= #{ranges.queryStart}
  and o.updated_at < #{ranges.queryEnd}
